-- 0353_safety_knowledge.sql
-- A03 Domain Data. Safety (Section 7.4 Safety, invariant 22, Section 3.7, Section 8.3): inspection
-- templates, items, inspections with sign-off and results, permit requirements generated by the
-- jurisdiction permit engine (an unpopulated jurisdiction answers nothing), incidents (a critical
-- incident cannot be relabeled and closed in one statement; closing requires sign-off), parties,
-- media, dispatch, medical encounters with Restricted notes, crisis alerts and radio channels.
-- Knowledge: SOPs with acknowledgments, documents with append-only versions, and verbiage terms that
-- refuse the em dash (invariant 24). Emergency codes are global canon (decision D15), not copied here.

-- Inspections -------------------------------------------------------------------------------------------

create table app.inspection_templates (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  name text not null,
  deleted_at timestamptz,
  constraint inspection_templates_name_length check (char_length(btrim(name)) between 1 and 200)
);
call private.install_domain_table('app.inspection_templates');
call private.install_policies('app.inspection_templates',
  $$org_id in (select private.my_org_ids())$$,
  $$org_id in (select private.orgs_with_capability('safety.inspection_template.write'))$$);
call private.describe('app.inspection_templates', 'Reusable inspection checklists.', array['name', 'Template name.']);

create table app.inspection_items (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  inspection_template_id uuid not null references app.inspection_templates (id),
  position integer not null,
  prompt text not null,
  is_critical boolean not null default false,
  deleted_at timestamptz,
  constraint inspection_items_position_positive check (position > 0)
);
create unique index inspection_items_position_key on app.inspection_items (inspection_template_id, position) where deleted_at is null;
call private.install_domain_table('app.inspection_items', 'app.inspection_templates', 'inspection_template_id');
call private.install_policies('app.inspection_items',
  $$org_id in (select private.my_org_ids())$$,
  $$org_id in (select private.orgs_with_capability('safety.inspection_template.write'))$$);
call private.describe('app.inspection_items', 'Items of an inspection template.', array[
  'inspection_template_id', 'Template.', 'position', 'Order in the template.', 'prompt', 'What is checked.', 'is_critical', 'True when a failure stops use.'
]);

create table app.inspections (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  project_id uuid not null references app.projects (id),
  inspection_template_id uuid not null references app.inspection_templates (id),
  record_id uuid references app.records (id),
  inspector_person_id uuid references app.people (id),
  inspected_at timestamptz not null default now(),
  signed_off_by uuid references app.people (id),
  signed_off_at timestamptz,
  deleted_at timestamptz,
  constraint inspections_signoff_pair check ((signed_off_by is null) = (signed_off_at is null))
);
create index inspections_project_id_idx on app.inspections (project_id);
create index inspections_template_idx on app.inspections (inspection_template_id);
create index inspections_record_id_idx on app.inspections (record_id);
create index inspections_inspector_idx on app.inspections (inspector_person_id);
create index inspections_signed_off_by_idx on app.inspections (signed_off_by);
call private.install_project_table('app.inspections', 'safety.inspection.read', 'safety.inspection.write',
  array['app.inspection_templates', 'inspection_template_id', 'app.records', 'record_id']);
call private.describe('app.inspections', 'Inspections performed on a project from a template. Sign-off needs safety.inspection.sign_off and is never by the inspector.', array[
  'project_id', 'Project.', 'inspection_template_id', 'Template used.', 'record_id', 'Inspection record of the same project, when one tracks it.',
  'inspector_person_id', 'Inspector, from the session.', 'inspected_at', 'When the inspection took place.', 'signed_off_by', 'Who signed it off.', 'signed_off_at', 'When.'
]);

create or replace function private.guard_inspection()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.inspector_person_id := coalesce(private.current_person_id(), new.inspector_person_id);
    new.signed_off_by := null;
    new.signed_off_at := null;
  elsif new.inspector_person_id is distinct from old.inspector_person_id then
    perform private.refuse('inspection_inspector_immutable', 'An inspection keeps its inspector.');
  elsif old.signed_off_at is not null then
    new.signed_off_by := old.signed_off_by;
    new.signed_off_at := old.signed_off_at;
  elsif new.signed_off_at is not null then
    if auth.uid() is not null and not private.can_on_project(new.project_id, 'safety.inspection.sign_off') then
      raise exception using errcode = '42501', message = 'safety.inspection.sign_off is required';
    end if;
    perform private.assert_separation('sod_approval_requester', private.current_person_id(), new.inspector_person_id);
    new.signed_off_by := private.current_person_id();
    new.signed_off_at := now();
  end if;
  return new;
end;
$$;
comment on function private.guard_inspection() is 'Inspections: inspector from the session; sign-off once, by someone with safety.inspection.sign_off other than the inspector.';
revoke all on function private.guard_inspection() from public, anon, authenticated;
create trigger t40_guard_inspection before insert or update on app.inspections for each row execute function private.guard_inspection();
create trigger t39_inspection_project before insert or update on app.inspections
  for each row execute function private.assert_same_project('app.records', 'record_id');

create table app.inspection_results (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  inspection_id uuid not null references app.inspections (id),
  inspection_item_id uuid not null references app.inspection_items (id),
  result_enum_id text not null references xpms.std_enumeration (record_id),
  note text,
  deleted_at timestamptz
);
create index inspection_results_inspection_idx on app.inspection_results (inspection_id);
create index inspection_results_item_idx on app.inspection_results (inspection_item_id);
create index inspection_results_result_idx on app.inspection_results (result_enum_id);
create unique index inspection_results_item_key on app.inspection_results (inspection_id, inspection_item_id) where deleted_at is null;
call private.install_child_table('app.inspection_results', 'app.inspections', 'inspection_id', 'safety.inspection.read', 'safety.inspection.write',
  array['app.inspection_items', 'inspection_item_id']);
call private.describe('app.inspection_results', 'One result per template item of an inspection, from the canon Inspection Result enumeration. Results freeze at sign-off.', array[
  'inspection_id', 'Inspection.', 'inspection_item_id', 'Item of the inspection''s template.', 'result_enum_id', 'Result: a row of the canon Inspection Result enumeration.', 'note', 'Finding.'
]);

create or replace function private.guard_inspection_result()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_inspection app.inspections;
begin
  select * into v_inspection from app.inspections i where i.id = new.inspection_id;
  if v_inspection.signed_off_at is not null then
    perform private.refuse('inspection_signed_off', 'A signed-off inspection''s results never change.');
  end if;
  if (select it.inspection_template_id from app.inspection_items it where it.id = new.inspection_item_id) <> v_inspection.inspection_template_id then
    perform private.refuse('inspection_item_template', 'A result answers an item of the inspection''s template.');
  end if;
  perform private.assert_enumeration(new.result_enum_id, 'Inspection Result');
  return new;
end;
$$;
comment on function private.guard_inspection_result() is 'Inspection results answer items of the inspection''s template with canon results and freeze at sign-off.';
revoke all on function private.guard_inspection_result() from public, anon, authenticated;
create trigger t40_guard_inspection_result before insert or update on app.inspection_results for each row execute function private.guard_inspection_result();

-- Permit engine (Section 3.7) ---------------------------------------------------------------------------------

create table app.permit_requirements (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  project_id uuid not null references app.projects (id),
  permit_rule text not null references xpms.dim_permit_rule (rule),
  record_id uuid references app.records (id),
  deleted_at timestamptz
);
create index permit_requirements_project_id_idx on app.permit_requirements (project_id);
create index permit_requirements_rule_idx on app.permit_requirements (permit_rule);
create index permit_requirements_record_id_idx on app.permit_requirements (record_id);
create unique index permit_requirements_rule_key on app.permit_requirements (project_id, permit_rule) where deleted_at is null;
call private.install_project_table('app.permit_requirements', 'safety.permit.read', 'safety.permit.write', array['app.records', 'record_id']);
call private.describe('app.permit_requirements', 'Permits a project needs, generated by app.generate_permit_requirements from the canon permit rules of the project''s jurisdiction chain (Bible tab 15). A permit record of the same project tracks each one.', array[
  'project_id', 'Project.', 'permit_rule', 'Canon permit rule that requires the permit.', 'record_id', 'Permit record tracking it.'
]);
create trigger t39_permit_requirement_project before insert or update on app.permit_requirements
  for each row execute function private.assert_same_project('app.records', 'record_id');

create or replace function app.generate_permit_requirements(p_project_id uuid)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_project app.projects;
  v_status text;
  v_count integer;
begin
  perform private.require_person();
  if not private.can_on_project(p_project_id, 'safety.permit.write') then
    raise exception using errcode = '42501', message = 'safety.permit.write is required on the project';
  end if;
  select * into v_project from app.projects p where p.id = p_project_id;
  if v_project.jurisdiction_id is null then
    perform private.refuse('jurisdiction_no_answer', 'NO_ANSWER: the project''s jurisdiction is unresolved, so permit questions have no answer.');
  end if;
  select j.status into v_status from xpms.jurisdiction j where j.jurisdiction_id = v_project.jurisdiction_id;
  if v_status <> 'populated' then
    perform private.refuse('jurisdiction_no_answer', 'NO_ANSWER: the project''s jurisdiction is declared but unpopulated; it never passes.');
  end if;
  with recursive chain (jurisdiction_id, parent) as (
    select j.jurisdiction_id, j.parent from xpms.jurisdiction j where j.jurisdiction_id = v_project.jurisdiction_id
    union all
    select j.jurisdiction_id, j.parent from xpms.jurisdiction j join chain c on j.jurisdiction_id = c.parent
  ), inserted as (
    insert into app.permit_requirements (project_id, permit_rule)
    select p_project_id, r.rule from xpms.dim_permit_rule r
    where r.jurisdiction_id in (select c.jurisdiction_id from chain c)
      and not exists (select 1 from app.permit_requirements e where e.project_id = p_project_id and e.permit_rule = r.rule and e.deleted_at is null)
    returning 1
  )
  select count(*) into v_count from inserted;
  return v_count;
end;
$$;
comment on function app.generate_permit_requirements(uuid) is 'The jurisdiction permit engine: adds every canon permit rule of the project''s jurisdiction and its parents. An unresolved or unpopulated jurisdiction is refused with NO_ANSWER (Section 3.7), never passed. Returns the number of requirements added.';
revoke all on function app.generate_permit_requirements(uuid) from public, anon;
grant execute on function app.generate_permit_requirements(uuid) to authenticated, service_role;

-- Incidents (invariant 22) ------------------------------------------------------------------------------------

create type app.incident_state as enum ('Reported', 'Dispatched', 'Contained', 'Closed');
comment on type app.incident_state is 'Incident lifecycle. Closing needs sign-off through app.close_incident.';

insert into private.lifecycle_transition_rules (lifecycle, from_state, to_state) values
  ('incident', 'Reported', 'Dispatched'),
  ('incident', 'Reported', 'Contained'),
  ('incident', 'Dispatched', 'Contained'),
  ('incident', 'Contained', 'Dispatched'),
  ('incident', 'Contained', 'Closed');

insert into private.domain_event_types (code, subject, description) values
  ('incident.reported', 'incidents', 'An incident was reported.'),
  ('incident.state_changed', 'incidents', 'An incident moved to another incident state.'),
  ('incident.closed', 'incidents', 'An incident was closed with sign-off.'),
  ('crisis_alert.issued', 'crisis_alerts', 'A crisis alert was issued.');

create table app.incidents (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  project_id uuid not null references app.projects (id),
  incident_number bigint not null default 0,
  title text not null,
  severity_enum_id text not null references xpms.std_enumeration (record_id),
  zone_id uuid references app.zones (id),
  occurred_at timestamptz not null,
  reported_by uuid references app.people (id),
  incident_state app.incident_state not null default 'Reported',
  closed_signed_off_by uuid references app.people (id),
  deleted_at timestamptz,
  constraint incidents_title_length check (char_length(btrim(title)) between 1 and 200)
);
create index incidents_project_id_idx on app.incidents (project_id);
create unique index incidents_project_number_key on app.incidents (project_id, incident_number);
create index incidents_severity_idx on app.incidents (severity_enum_id);
create index incidents_zone_id_idx on app.incidents (zone_id);
create index incidents_reported_by_idx on app.incidents (reported_by);
create index incidents_closed_signed_off_by_idx on app.incidents (closed_signed_off_by);
call private.install_project_table('app.incidents', 'safety.incident.read', 'safety.incident.write', array['app.zones', 'zone_id']);
call private.describe('app.incidents', 'Incidents of a project (Incident CAD log). A critical incident cannot be relabeled and closed in one statement, and closing requires sign-off (invariant 22).', array[
  'project_id', 'Project.', 'incident_number', 'Number from the project''s display key sequence.', 'title', 'What happened.',
  'severity_enum_id', 'Severity: a row of the canon Incident Severity enumeration; Level 1 - Critical is critical.', 'zone_id', 'Zone where it happened.',
  'occurred_at', 'When it happened.', 'reported_by', 'Reporter, from the session.', 'incident_state', 'Incident state. Changes only through the incident RPCs.',
  'closed_signed_off_by', 'Person who signed off the closure.'
]);
call private.install_lifecycle('app.incidents', 'incident_id', 'incident_state', 'incident', 'Reported',
  $$incident_id in (select i.id from app.incidents i where i.project_id in (select private.project_ids_with('safety.incident.read')))$$);
create trigger t35_incident_number before insert or update on app.incidents
  for each row execute function private.number_from_project_sequence('incident_number');
create trigger t90_emit_incident_reported after insert on app.incidents
  for each row execute function private.emit_subject_event('incident.reported', 'incidents', 'id', 'incident_number', 'severity_enum_id', 'occurred_at');
create trigger t90_emit_incident_state after insert on app.incident_state_transitions
  for each row when (new.from_state is not null and new.to_state <> 'Closed')
  execute function private.emit_subject_event('incident.state_changed', 'incidents', 'incident_id', 'from_state', 'to_state');
create trigger t90_emit_incident_closed after insert on app.incident_state_transitions
  for each row when (new.to_state = 'Closed')
  execute function private.emit_subject_event('incident.closed', 'incidents', 'incident_id', 'from_state', 'to_state', 'reason');

create or replace function private.is_critical_severity(p_enum_id text)
returns boolean
language sql
stable
set search_path = ''
as $$
  select exists (select 1 from xpms.std_enumeration e where e.record_id = p_enum_id and e.enum_domain = 'Incident Severity'
                 and e.sort_order = (select min(s.sort_order) from xpms.std_enumeration s where s.enum_domain = 'Incident Severity'));
$$;
comment on function private.is_critical_severity(text) is 'True for the most severe canon Incident Severity value (Level 1 - Critical), read from canon order rather than retyped.';
revoke all on function private.is_critical_severity(text) from public, anon, authenticated;

create or replace function private.guard_incident()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.assert_enumeration(new.severity_enum_id, 'Incident Severity');
  if tg_op = 'INSERT' then
    perform private.assert_production_open(new.project_id);
    new.reported_by := coalesce(private.current_person_id(), new.reported_by);
    new.closed_signed_off_by := null;
    return new;
  end if;
  if new.severity_enum_id <> old.severity_enum_id and new.incident_state = 'Closed' and old.incident_state <> 'Closed'
     and private.is_critical_severity(old.severity_enum_id) then
    perform private.refuse('incident_relabel_and_close', 'A critical incident cannot be relabeled and closed in one statement.');
  end if;
  if old.incident_state = 'Closed' and new.severity_enum_id <> old.severity_enum_id then
    perform private.refuse('incident_closed', 'A closed incident is never relabeled.');
  end if;
  if new.reported_by is distinct from old.reported_by then
    perform private.refuse('incident_reporter_immutable', 'An incident keeps its reporter.');
  end if;
  if new.closed_signed_off_by is distinct from old.closed_signed_off_by and not private.in_trusted_operation('incident_transition') then
    perform private.refuse('incident_signoff_rpc', 'Closure sign-off is recorded only by app.close_incident.');
  end if;
  return new;
end;
$$;
comment on function private.guard_incident() is 'Incidents: canon severity, reporter from the session, no new incident on a closed production; invariant 22 refuses relabeling a critical incident and closing it in one statement; sign-off only through app.close_incident.';
revoke all on function private.guard_incident() from public, anon, authenticated;
create trigger t39_guard_incident before insert or update on app.incidents for each row execute function private.guard_incident();

create or replace function app.transition_incident(p_incident_id uuid, p_expected app.incident_state, p_next app.incident_state, p_reason text)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_project uuid := (select i.project_id from app.incidents i where i.id = p_incident_id and i.deleted_at is null);
begin
  if p_next = 'Closed' then
    perform private.refuse('incident_close_rpc', 'Close an incident through app.close_incident, which records sign-off.');
  end if;
  perform private.require_person();
  if v_project is null or not private.can_on_project(v_project, case when p_next = 'Dispatched' then 'safety.incident.dispatch' else 'safety.incident.write' end) then
    raise exception using errcode = '42501', message = 'the person may not move this incident';
  end if;
  return private.transition_lifecycle('incident', 'app.incidents', 'incident_state', 'app.incident_state_transitions',
    'incident_id', p_incident_id, p_expected::text, p_next::text, p_reason);
end;
$$;
comment on function app.transition_incident(uuid, app.incident_state, app.incident_state, text) is 'Dispatches or contains an incident with compare-and-set. Closing goes through app.close_incident.';
revoke all on function app.transition_incident(uuid, app.incident_state, app.incident_state, text) from public, anon;
grant execute on function app.transition_incident(uuid, app.incident_state, app.incident_state, text) to authenticated, service_role;

create or replace function app.close_incident(p_incident_id uuid, p_signoff_note text)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_person uuid := private.require_person();
  v_incident app.incidents;
  v_entry uuid;
begin
  select * into v_incident from app.incidents i where i.id = p_incident_id and i.deleted_at is null for update;
  if v_incident.id is null or not private.can_on_project(v_incident.project_id, 'safety.incident.close') then
    raise exception using errcode = '42501', message = 'safety.incident.close is required on the project';
  end if;
  if private.is_critical_severity(v_incident.severity_enum_id) then
    perform private.assert_separation('sod_approval_requester', v_person, v_incident.reported_by);
  end if;
  perform private.begin_trusted_operation('incident_transition');
  update app.incidents set closed_signed_off_by = v_person where id = p_incident_id;
  v_entry := private.transition_lifecycle('incident', 'app.incidents', 'incident_state', 'app.incident_state_transitions',
    'incident_id', p_incident_id, 'Contained', 'Closed', p_signoff_note);
  perform private.end_trusted_operation('incident_transition');
  return v_entry;
end;
$$;
comment on function app.close_incident(uuid, text) is 'Closes a contained incident with sign-off (invariant 22): safety.incident.close on the project; a critical incident is signed off by someone other than its reporter. The sign-off note is the ledger reason.';
revoke all on function app.close_incident(uuid, text) from public, anon;
grant execute on function app.close_incident(uuid, text) to authenticated, service_role;

