revoke select on app.medical_encounters from authenticated;
grant select (id, org_id, incident_id, patient_description, disposition, created_at, created_by, updated_at, updated_by, deleted_at)
  on app.medical_encounters to authenticated;

create view app.medical_encounters_masked as
select m.id, m.org_id, m.incident_id, m.patient_description, m.disposition,
  case when private.has_capability(m.org_id, 'data.restricted.read.medical') then m.treatment_notes end as treatment_notes,
  not private.has_capability(m.org_id, 'data.restricted.read.medical') as is_masked
from app.medical_encounters m
where m.deleted_at is null
  and m.incident_id in (select i.id from app.incidents i where i.project_id in (select private.project_ids_with('safety.incident.read')));
call private.describe('app.medical_encounters_masked', 'Medical encounters with Restricted treatment notes masked unless the caller holds data.restricted.read.medical.', array[
  'id', 'Encounter.', 'org_id', 'Org.', 'incident_id', 'Incident.', 'patient_description', 'Who was treated.', 'disposition', 'Outcome.',
  'treatment_notes', 'Treatment given, or NULL when masked.', 'is_masked', 'True when the notes are withheld from the caller.'
]);
revoke all on app.medical_encounters_masked from public, anon;
grant select on app.medical_encounters_masked to authenticated, service_role;

create table app.crisis_alerts (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  project_id uuid not null references app.projects (id),
  emergency_code text not null references xpms.emergency_code (code),
  message text not null,
  issued_at timestamptz not null default now(),
  ended_at timestamptz,
  deleted_at timestamptz,
  constraint crisis_alerts_window check (ended_at is null or ended_at >= issued_at)
);
create index crisis_alerts_project_id_idx on app.crisis_alerts (project_id);
create index crisis_alerts_code_idx on app.crisis_alerts (emergency_code);
call private.install_project_table('app.crisis_alerts', 'safety.incident.read', 'safety.incident.dispatch');
call private.describe('app.crisis_alerts', 'Crisis alerts announced on a project under a global canon emergency code (decision D15).', array[
  'project_id', 'Project.', 'emergency_code', 'Canon emergency code announced.', 'message', 'Announcement.', 'issued_at', 'When issued.', 'ended_at', 'When the all-clear was given.'
]);
create trigger t90_emit_crisis_alert after insert on app.crisis_alerts
  for each row execute function private.emit_subject_event('crisis_alert.issued', 'crisis_alerts', 'id', 'emergency_code', 'issued_at');

create table app.radio_channels (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  project_id uuid not null references app.projects (id),
  channel_number integer not null,
  name text not null,
  zone_id uuid references app.zones (id),
  deleted_at timestamptz,
  constraint radio_channels_number_positive check (channel_number > 0)
);
create unique index radio_channels_number_key on app.radio_channels (project_id, channel_number) where deleted_at is null;
create index radio_channels_zone_idx on app.radio_channels (zone_id);
call private.install_project_table('app.radio_channels', 'safety.incident.read', 'safety.radio_channel.write', array['app.zones', 'zone_id']);
call private.describe('app.radio_channels', 'The radio plan of a project, listed in channel number order.', array[
  'project_id', 'Project.', 'channel_number', 'Channel number, unique per project.', 'name', 'Channel name.', 'zone_id', 'Zone the channel covers.'
]);

-- Knowledge (invariant 24) ---------------------------------------------------------------------------------------

create table app.sops (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  code text not null,
  title text not null,
  body text not null,
  version integer not null default 1,
  published_at timestamptz,
  deleted_at timestamptz,
  constraint sops_code_format check (code ~ '^SOP-[0-9]{3,5}$'),
  constraint sops_version_positive check (version > 0)
);
create unique index sops_code_key on app.sops (org_id, code) where deleted_at is null;
call private.install_domain_table('app.sops');
call private.install_policies('app.sops',
  $$org_id in (select private.orgs_with_capability('knowledge.sop.read'))$$,
  $$org_id in (select private.orgs_with_capability('knowledge.sop.write'))$$);
call private.describe('app.sops', 'Standard operating procedures. Publishing a new version asks everyone to acknowledge again. Listed in code order.', array[
  'code', 'SOP code, such as SOP-001.', 'title', 'SOP title.', 'body', 'Procedure as rich text.', 'version', 'Version number, raised on each publish.', 'published_at', 'When the current version was published.'
]);

create or replace function private.guard_sop()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' and new.published_at is distinct from old.published_at and new.published_at is not null then
    if auth.uid() is not null and not private.has_capability(new.org_id, 'knowledge.sop.publish') then
      raise exception using errcode = '42501', message = 'knowledge.sop.publish is required';
    end if;
    new.published_at := now();
    new.version := old.version + case when old.published_at is null then 0 else 1 end;
  elsif tg_op = 'UPDATE' and new.version <> old.version then
    perform private.refuse('sop_version_managed', 'The SOP version rises only when it is published.');
  end if;
  return new;
end;
$$;
comment on function private.guard_sop() is 'SOPs: publishing needs knowledge.sop.publish and raises the version; the version is never set by hand.';
revoke all on function private.guard_sop() from public, anon, authenticated;
create trigger t40_guard_sop before insert or update on app.sops for each row execute function private.guard_sop();

create table app.sop_acknowledgments (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  sop_id uuid not null references app.sops (id),
  person_id uuid not null references app.people (id),
  sop_version integer not null,
  acknowledged_at timestamptz not null default now()
);
create index sop_acknowledgments_sop_idx on app.sop_acknowledgments (sop_id);
create index sop_acknowledgments_person_idx on app.sop_acknowledgments (person_id);
create unique index sop_acknowledgments_once on app.sop_acknowledgments (sop_id, person_id, sop_version);
call private.install_domain_table('app.sop_acknowledgments', 'app.sops', 'sop_id', '{}', true);
call private.install_policies('app.sop_acknowledgments',
  $$person_id = (select private.current_person_id()) or org_id in (select private.orgs_with_capability('knowledge.sop.write'))$$,
  $$person_id = (select private.current_person_id())$$);
revoke update on app.sop_acknowledgments from authenticated;
drop policy sop_acknowledgments_update on app.sop_acknowledgments;
call private.describe('app.sop_acknowledgments', 'Append-only acknowledgments: a person confirms they read a published SOP version. Only the person acknowledges for themselves.', array[
  'sop_id', 'SOP.', 'person_id', 'Person acknowledging; always the signed-in person.', 'sop_version', 'Version acknowledged, the current published one.', 'acknowledged_at', 'When, set by the database.'
]);

create or replace function private.guard_sop_acknowledgment()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sop app.sops;
begin
  select * into v_sop from app.sops s where s.id = new.sop_id;
  if v_sop.published_at is null then
    perform private.refuse('sop_unpublished', 'Only a published SOP is acknowledged.');
  end if;
  if auth.uid() is not null and new.person_id is distinct from private.current_person_id() then
    perform private.refuse('sop_acknowledge_self', 'A person acknowledges an SOP only for themselves.');
  end if;
  new.sop_version := v_sop.version;
  new.acknowledged_at := now();
  return new;
end;
$$;
comment on function private.guard_sop_acknowledgment() is 'Acknowledgments are for published SOPs, by the person themselves, at the current version and database time.';
revoke all on function private.guard_sop_acknowledgment() from public, anon, authenticated;
create trigger t40_guard_sop_acknowledgment before insert on app.sop_acknowledgments for each row execute function private.guard_sop_acknowledgment();

create table app.documents (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  project_id uuid references app.projects (id),
  title text not null,
  deleted_at timestamptz,
  constraint documents_title_length check (char_length(btrim(title)) between 1 and 200)
);
create index documents_project_id_idx on app.documents (project_id);
call private.install_domain_table('app.documents', null, null, array['app.projects', 'project_id']);
call private.install_policies('app.documents',
  $$(project_id is null and org_id in (select private.orgs_with_capability('knowledge.document.read')))
    or project_id in (select private.project_ids_with('knowledge.document.read'))$$,
  $$(project_id is null and org_id in (select private.orgs_with_capability('knowledge.document.write')))
    or project_id in (select private.project_ids_with('knowledge.document.write'))$$);
call private.describe('app.documents', 'Documents of the org or of a project; project documents follow invariant 2. Content lives in append-only versions.', array[
  'project_id', 'Project the document belongs to; NULL for an org-wide document.', 'title', 'Document title.'
]);

create table app.document_versions (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  document_id uuid not null references app.documents (id),
  version_number integer not null default 0,
  storage_uri text not null,
  checksum_sha256 text not null,
  constraint document_versions_checksum_format check (checksum_sha256 ~ '^[0-9a-f]{64}$')
);
create unique index document_versions_number_key on app.document_versions (document_id, version_number);
call private.install_domain_table('app.document_versions', 'app.documents', 'document_id', '{}', true);
call private.install_policies('app.document_versions',
  $$document_id in (select d.id from app.documents d where (d.project_id is null and d.org_id in (select private.orgs_with_capability('knowledge.document.read')))
    or d.project_id in (select private.project_ids_with('knowledge.document.read')))$$,
  $$document_id in (select d.id from app.documents d where (d.project_id is null and d.org_id in (select private.orgs_with_capability('knowledge.document.write')))
    or d.project_id in (select private.project_ids_with('knowledge.document.write')))$$);
revoke update on app.document_versions from authenticated;
drop policy document_versions_update on app.document_versions;
call private.describe('app.document_versions', 'Append-only versions of a document, numbered by the database.', array[
  'document_id', 'Document.', 'version_number', 'Version number within the document, issued by the database.', 'storage_uri', 'Where the file is stored.', 'checksum_sha256', 'SHA-256 of the file, lowercase hex.'
]);

create or replace function private.number_document_version()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.version_number := private.next_sequence(new.org_id, 'document:' || new.document_id::text);
  return new;
end;
$$;
comment on function private.number_document_version() is 'Numbers document versions from a per-document sequence.';
revoke all on function private.number_document_version() from public, anon, authenticated;
create trigger t40_number_document_version before insert on app.document_versions for each row execute function private.number_document_version();

create table app.verbiage_terms (
  id uuid primary key default private.uuid_v7(),
  org_id uuid not null references app.organizations (id),
  term text not null,
  casing_rule text not null,
  definition text not null,
  deleted_at timestamptz,
  constraint verbiage_terms_term_length check (char_length(btrim(term)) between 1 and 200),
  constraint verbiage_terms_no_em_dash check (strpos(term, chr(8212)) = 0 and strpos(casing_rule, chr(8212)) = 0 and strpos(definition, chr(8212)) = 0),
  constraint verbiage_terms_definition_sentence check (definition ~ '[.]$')
);
create unique index verbiage_terms_term_key on app.verbiage_terms (org_id, lower(term)) where deleted_at is null;
call private.install_domain_table('app.verbiage_terms');
call private.install_policies('app.verbiage_terms',
  $$org_id in (select private.orgs_with_capability('knowledge.verbiage.read'))$$,
  $$org_id in (select private.orgs_with_capability('knowledge.verbiage.write'))$$);
call private.describe('app.verbiage_terms', 'The org''s controlled vocabulary with casing rules. No em dash is accepted in any verbiage text (invariant 24); definitions are period-terminated sentences.', array[
  'term', 'Term, unique within the org ignoring case.', 'casing_rule', 'How the term is cased, for example Title Case in labels.', 'definition', 'Sentence-case definition ending in a period.'
]);
